// Presentation only. HTML fragments and attribute strings are generated by the
// calling UI after escaping user data and resolving that surface's authority.
// Message IDs, account ownership and upload grants are never inferred here.
export function renderDirectMessageFrame({classes = 'msg', attributes = '', avatarColumnHtml = '',
  actionsHtml = '', metaHtml = '', replyHtml = '', bodyClass = 'msg__text msg__text--plain', bodyHtml = '',
  afterBodyHtml = '', reactionsHtml = '', reactionsAttributes = ''} = {}) {
  return `
    <div class="${classes}"${attributes ? ` ${attributes}` : ''}>
      ${avatarColumnHtml}
      <div class="msg__body">
        ${actionsHtml}
        ${metaHtml}
        ${replyHtml}
        <div class="${bodyClass}">${bodyHtml}</div>
        ${afterBodyHtml}
        <div class="msg__reactions"${reactionsAttributes ? ` ${reactionsAttributes}` : ''}>${reactionsHtml}</div>
      </div>
    </div>
  `;
}
